import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./Archive.css";

function Archive() {
  const [archivedImages, setArchivedImages] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    // 로컬 스토리지에서 데이터 불러오기
    const archives = JSON.parse(localStorage.getItem("archivedImages") || "[]");
    setArchivedImages(archives);
  }, []);

  const handleDelete = (index) => {
    if (window.confirm("정말 이 그래픽을 삭제하시겠습니까?")) {
      const newArchives = archivedImages.filter((_, i) => i !== index);
      setArchivedImages(newArchives);
      localStorage.setItem("archivedImages", JSON.stringify(newArchives));
    }
  };

  const handleDownload = (imageData, index) => {
    const link = document.createElement('a');
    link.download = `archived-graphic-${index + 1}.png`;
    link.href = imageData;
    link.click();
  };

  return (
    <div className="ar-container">
      <div className="archive-header">
        <div className="archive-logo">
          {/* 로고 경로 확인 필요 */}
          <img src={process.env.PUBLIC_URL + '/images/logo_home.png'} alt="Archive Logo" />
        </div>
      </div>

      <div className="ar-main">
        <div className="ar-box1">
          <div className="intro">
            이곳은 생성된 그래픽들이 저장되는 아카이브입니다. 
            과거의 실험 결과들을 확인하고, 마음에 드는 결과물을 영구 소장하거나 삭제할 수 있습니다. 
            최대 20개까지 최신순으로 저장됩니다.
          </div>
          <div className="new-page">
            <h1 className="ar-list" onClick={() => navigate("/")} style={{ cursor: 'pointer' }}>HOME</h1>
            <h1 className="ar-list" onClick={() => navigate('/about')} style={{ cursor: 'pointer' }}>About</h1>
          </div>
        </div>

        <div className="ar-grid">
          {/* 데이터가 없을 경우 안내 메시지 */}
          {archivedImages.length === 0 && (
            <div className="ar-empty-state">
              <p>저장된 그래픽이 없습니다.</p>
              <button onClick={() => navigate("/")} className="ar-button">그래픽 만들러 가기</button>
            </div>
          )}

          {archivedImages.map((archive, index) => (
            <div key={archive.id || index} className="ar-item">
              <div className="ar-image-wrapper">
                <img 
                  src={archive.imageData} 
                  alt={`Archived ${index + 1}`}
                  className="ar-image"
                />
              </div>

              <div className="ar-info">
                <div className="ar-meta">
                  <span className="ar-date">
                    {archive.timestamp ? new Date(archive.timestamp).toLocaleDateString() : 'Unknown Date'}
                  </span>
                  <span className="ar-mode">
                    {archive.viewMode ? archive.viewMode.toUpperCase() : 'GRAPHIC'}
                  </span>
                </div>

                <div className="ar-actions">
                  <button 
                    onClick={() => handleDownload(archive.imageData, index)}
                    className="ar-button ar-button-download"
                  >
                    Save
                  </button>
                  {/* [추가됨] 삭제 버튼 */}
                  <button 
                    onClick={() => handleDelete(index)}
                    className="ar-button ar-button-delete"
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Archive;
